typedef enum
{
  NVRAM_OK                ,
  NVRAM_OK_RECOVERED      ,

  NVRAM_ERR_RANGE         ,

  NVRAM_ERR_WR_FAIL       ,

  NVRAM_ERR_CORRUPTED     ,

  NVRAM_ERR_INTERNAL      ,

  NVRAM_ERR_UNINITIALIZED ,

} Nvram_Status ;

